<?php defined('BASEPATH') or exit('No direct script access allowed');$portal_field=CompanyPortalOperationsSchema::target($portal_kind)['field'];$portal_labels=['contracts'=>'contratos','tickets'=>'chamados','projects'=>'projetos'];$portal_base=function($type,$child=null)use($hidden,$portal_parent,$portal_field,$esc){$hidden('portal_publish');echo '<input type="hidden" name="'.$esc($portal_field).'" value="'.(int)$portal_parent['id'].'"><input type="hidden" name="revision" value="'.(int)$portal_parent['revision'].'"><input type="hidden" name="publication_type" value="'.$esc($type).'">';if($type==='file')echo '<input type="hidden" name="file_key" value="'.$esc($child).'">';elseif($type==='reply')echo '<input type="hidden" name="reply_id" value="'.(int)$child.'">';}; ?>
<section class="company-settings-card" id="operation-portal-publication"><h3>Publicação no portal do cliente</h3><p>O acesso exige contato privado do cliente, permissão nativa específica e publicação explícita. Compartilhar cadastro não compartilha contato nem documento. Arquivos e mensagens internas permanecem privados até publicação individual. Anexos enviados por contato já são visíveis ao autor e à equipe; publicar amplia aos demais contatos autorizados do cadastro, despublicar retira somente essa ampliação. Para retirar todo acesso no portal, oculte o anexo.</p>
<?php if(!$portal_controls['private_client']){ ?><p>Este cadastro não pertence à empresa. Seus contatos não estão disponíveis para este documento.</p><?php } ?>
<?php if($can_edit&&$portal_controls['private_client']&&$portal_controls['eligible']){ ?><?= form_open($url());$portal_base('record'); ?><label><input type="checkbox" name="visible" value="1" <?= $portal_controls['visible']?'checked':''; ?>> Publicar este registro para contatos autorizados</label><button type="submit">Salvar publicação do registro</button><?= form_close(); ?><?php }elseif(!$portal_controls['eligible']){ ?><p>Ative o contrato antes de disponibilizar seu conteúdo no portal.</p><?php } ?>
<?php if($can_edit){foreach($portal_controls['files'] as $file){ ?><?= form_open($url());$portal_base('file',$file['file_key']); ?><label><input type="checkbox" name="visible" value="1" <?= (int)$file['visible']===1?'checked':''; ?>> Publicar anexo: <?= $esc($file['filename']); ?></label><button type="submit">Salvar publicação do anexo</button><?= form_close(); ?><?php }foreach($portal_controls['replies'] as $reply){ ?><?= form_open($url());$portal_base('reply',$reply['id']); ?><p style="white-space:pre-wrap"><?= $esc($reply['body']); ?></p><label><input type="checkbox" name="visible" value="1" <?= (int)$reply['visible']===1?'checked':''; ?>> Publicar esta mensagem no portal</label><button type="submit">Salvar publicação da mensagem</button><?= form_close(); ?><?php }} ?>
<?php if($portal_controls['permissions']){ ?><h4>Acesso nativo por contato</h4><p>A permissão vale para <?= $esc($portal_labels[$portal_kind]); ?> publicados deste cliente nesta empresa. Não concede acesso a faturas ou a outros domínios.</p><?php foreach($portal_controls['permissions'] as $contact=>$permission){ ?><?= form_open($url());$hidden('portal_permission'); ?><input type="hidden" name="<?= $esc($portal_field); ?>" value="<?= (int)$portal_parent['id']; ?>"><input type="hidden" name="contact_id" value="<?= (int)$contact; ?>"><input type="hidden" name="contact_revision" value="<?= $esc($permission['revision']); ?>"><label><input type="checkbox" name="allowed" value="1" <?= $permission['allowed']?'checked':''; ?> <?= $portal_controls['can_contact_edit']?'':'disabled'; ?>> <?= $esc($permission['name']); ?></label><?php if($portal_controls['can_contact_edit']){ ?><button type="submit">Salvar acesso nativo no portal</button><?php } ?><?= form_close(); ?><?php }} ?></section>
